// ========================================
// Workflow C v1.2 - 飞书去重分析工具
// 新增：定时自动执行（每周日23:00）
// ========================================

const tableData = $input.first().json;
const records = tableData.data?.items || [];

console.log(`\n========================================`);
console.log(`📊 飞书多维表格去重分析报告 v1.2`);
console.log(`========================================`);
console.log(`执行时间: ${new Date().toLocaleString('zh-CN', {timeZone: 'Asia/Shanghai'})}`);
console.log(`总记录数: ${records.length}`);

if (records.length === 0) {
  console.warn('⚠️ 未读取到任何记录');
  return [];
}

// 安全提取飞书字段的函数
function extractFeishuField(field, defaultValue = '') {
  if (!field) return defaultValue;
  if (typeof field === 'string') return field;

  if (Array.isArray(field)) {
    if (field.length === 0) return defaultValue;
    if (field[0] && typeof field[0] === 'object' && field[0].text) {
      return field.map(item => item.text).join(', ');
    }
    return field.join(', ');
  }

  if (typeof field === 'object') {
    if (field.text) return field.text;
    if (field.link) return field.link;
  }

  return String(field);
}

function extractUrl(urlField) {
  if (!urlField) return '';
  if (typeof urlField === 'string') return urlField;
  if (typeof urlField === 'object' && urlField.link) return urlField.link;
  if (Array.isArray(urlField) && urlField[0]?.link) return urlField[0].link;
  return '';
}

// 🆕 URL标准化（与Workflow A v2.1保持一致）
function normalizeUrl(url) {
  if (!url) return '';
  try {
    let normalized = url.toLowerCase().trim();
    normalized = normalized.replace(/^(https?:\/\/)?(www\.)?/, '');
    normalized = normalized.replace(/\/$/, '');
    return normalized;
  } catch (e) {
    return url.toLowerCase().trim();
  }
}

// 标准化标题
function normalizeTitle(title) {
  if (!title) return '';
  return title
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ')
    .replace(/[.,;:!?'"()（）【】「」\[\]]/g, '');
}

// 建立索引，识别重复记录
const urlIndex = new Map();
const titleIndex = new Map();
const normalizedUrlIndex = new Map();
const normalizedTitleIndex = new Map();

const duplicateGroups = [];
const uniqueRecords = [];
const recordsToDelete = [];

// 第一轮：按URL和标题分组
records.forEach((record, index) => {
  const fields = record.fields;
  const url = extractUrl(fields.url);
  const title = extractFeishuField(fields.title, '');
  const source = extractFeishuField(fields.source, '');
  const pubDate = fields.publish_date;

  const recordInfo = {
    record_id: record.record_id,
    index: index,
    url: url,
    title: title,
    source: source,
    pubDate: pubDate,
    normalizedUrl: normalizeUrl(url),
    normalizedTitle: normalizeTitle(title)
  };

  // URL精确匹配
  if (url) {
    const urlKey = url.toLowerCase().trim();
    if (!urlIndex.has(urlKey)) {
      urlIndex.set(urlKey, []);
    }
    urlIndex.get(urlKey).push(recordInfo);
  }

  // 🆕 URL标准化匹配
  if (recordInfo.normalizedUrl) {
    if (!normalizedUrlIndex.has(recordInfo.normalizedUrl)) {
      normalizedUrlIndex.set(recordInfo.normalizedUrl, []);
    }
    normalizedUrlIndex.get(recordInfo.normalizedUrl).push(recordInfo);
  }

  // 标题精确匹配
  if (title) {
    const titleKey = title.toLowerCase().trim();
    if (!titleIndex.has(titleKey)) {
      titleIndex.set(titleKey, []);
    }
    titleIndex.get(titleKey).push(recordInfo);
  }

  // 🆕 标题标准化匹配
  if (recordInfo.normalizedTitle) {
    if (!normalizedTitleIndex.has(recordInfo.normalizedTitle)) {
      normalizedTitleIndex.set(recordInfo.normalizedTitle, []);
    }
    normalizedTitleIndex.get(recordInfo.normalizedTitle).push(recordInfo);
  }
});

// 统计重复情况
let urlExactDuplicates = 0;
let urlNormalizedDuplicates = 0;
let titleExactDuplicates = 0;
let titleNormalizedDuplicates = 0;

const processedRecordIds = new Set();

// 处理URL精确重复
urlIndex.forEach((group, url) => {
  if (group.length > 1) {
    urlExactDuplicates += group.length - 1;

    // 按日期排序，保留最新的
    group.sort((a, b) => {
      const dateA = a.pubDate || 0;
      const dateB = b.pubDate || 0;
      return dateB - dateA;
    });

    duplicateGroups.push({
      type: 'URL精确重复',
      key: url,
      count: group.length,
      records: group,
      keepRecord: group[0],
      deleteRecords: group.slice(1)
    });

    // 标记要保留和删除的记录
    processedRecordIds.add(group[0].record_id);
    group.slice(1).forEach(r => {
      processedRecordIds.add(r.record_id);
      recordsToDelete.push({
        record_id: r.record_id,
        reason: 'URL精确重复',
        duplicate_of: group[0].record_id,
        title: r.title,
        url: r.url
      });
    });
  }
});

// 🆕 处理URL标准化重复（排除已处理的精确重复）
normalizedUrlIndex.forEach((group, normalizedUrl) => {
  if (group.length > 1) {
    const unprocessed = group.filter(r => !processedRecordIds.has(r.record_id));
    if (unprocessed.length > 1) {
      urlNormalizedDuplicates += unprocessed.length - 1;

      unprocessed.sort((a, b) => {
        const dateA = a.pubDate || 0;
        const dateB = b.pubDate || 0;
        return dateB - dateA;
      });

      duplicateGroups.push({
        type: 'URL标准化重复',
        key: normalizedUrl,
        count: unprocessed.length,
        records: unprocessed,
        keepRecord: unprocessed[0],
        deleteRecords: unprocessed.slice(1)
      });

      processedRecordIds.add(unprocessed[0].record_id);
      unprocessed.slice(1).forEach(r => {
        processedRecordIds.add(r.record_id);
        recordsToDelete.push({
          record_id: r.record_id,
          reason: 'URL标准化重复(http/https差异)',
          duplicate_of: unprocessed[0].record_id,
          title: r.title,
          url: r.url
        });
      });
    }
  }
});

// 处理标题精确重复（排除已处理的URL重复）
titleIndex.forEach((group, title) => {
  if (group.length > 1) {
    const unprocessed = group.filter(r => !processedRecordIds.has(r.record_id));
    if (unprocessed.length > 1) {
      titleExactDuplicates += unprocessed.length - 1;

      unprocessed.sort((a, b) => {
        const dateA = a.pubDate || 0;
        const dateB = b.pubDate || 0;
        return dateB - dateA;
      });

      duplicateGroups.push({
        type: '标题精确重复',
        key: title,
        count: unprocessed.length,
        records: unprocessed,
        keepRecord: unprocessed[0],
        deleteRecords: unprocessed.slice(1)
      });

      processedRecordIds.add(unprocessed[0].record_id);
      unprocessed.slice(1).forEach(r => {
        processedRecordIds.add(r.record_id);
        recordsToDelete.push({
          record_id: r.record_id,
          reason: '标题精确重复',
          duplicate_of: unprocessed[0].record_id,
          title: r.title,
          url: r.url
        });
      });
    }
  }
});

// 🆕 处理标题标准化重复（排除已处理的）
normalizedTitleIndex.forEach((group, normalizedTitle) => {
  if (group.length > 1) {
    const unprocessed = group.filter(r => !processedRecordIds.has(r.record_id));
    if (unprocessed.length > 1) {
      titleNormalizedDuplicates += unprocessed.length - 1;

      unprocessed.sort((a, b) => {
        const dateA = a.pubDate || 0;
        const dateB = b.pubDate || 0;
        return dateB - dateA;
      });

      duplicateGroups.push({
        type: '标题标准化重复',
        key: normalizedTitle,
        count: unprocessed.length,
        records: unprocessed,
        keepRecord: unprocessed[0],
        deleteRecords: unprocessed.slice(1)
      });

      processedRecordIds.add(unprocessed[0].record_id);
      unprocessed.slice(1).forEach(r => {
        processedRecordIds.add(r.record_id);
        recordsToDelete.push({
          record_id: r.record_id,
          reason: '标题标准化重复(标点差异)',
          duplicate_of: unprocessed[0].record_id,
          title: r.title,
          url: r.url
        });
      });
    }
  }
});

// 生成报告
console.log(`\n📋 重复统计（增强版）：`);
console.log(`- URL精确重复: ${urlExactDuplicates} 条`);
console.log(`- URL标准化重复: ${urlNormalizedDuplicates} 条 🆕`);
console.log(`- 标题精确重复: ${titleExactDuplicates} 条`);
console.log(`- 标题标准化重复: ${titleNormalizedDuplicates} 条 🆕`);
console.log(`- 总计待删除: ${recordsToDelete.length} 条`);
console.log(`- 去重后剩余: ${records.length - recordsToDelete.length} 条`);
console.log(`- 去重率: ${((recordsToDelete.length / records.length) * 100).toFixed(1)}%`);

console.log(`\n🔍 重复组详情（前10组）：`);
duplicateGroups.slice(0, 10).forEach((group, i) => {
  console.log(`\n${i + 1}. ${group.type} - ${group.count}条记录`);
  console.log(`   关键字: ${group.key.substring(0, 50)}...`);
  console.log(`   保留: ${group.keepRecord.title.substring(0, 40)}...`);
  console.log(`   删除: ${group.deleteRecords.length}条`);
});

if (duplicateGroups.length > 10) {
  console.log(`\n... 还有 ${duplicateGroups.length - 10} 组重复记录`);
}

console.log(`\n========================================`);

// 返回待删除的记录ID列表
return [{
  json: {
    version: 'v1.2',
    execution_time: new Date().toISOString(),
    total_records: records.length,
    duplicate_count: recordsToDelete.length,
    unique_count: records.length - recordsToDelete.length,
    records_to_delete: recordsToDelete,
    duplicate_groups: duplicateGroups,
    summary: {
      url_exact_duplicates: urlExactDuplicates,
      url_normalized_duplicates: urlNormalizedDuplicates,
      title_exact_duplicates: titleExactDuplicates,
      title_normalized_duplicates: titleNormalizedDuplicates,
      total_to_delete: recordsToDelete.length,
      deduplication_rate: ((recordsToDelete.length / records.length) * 100).toFixed(1) + '%'
    }
  }
}];

// 分批处理删除请求（避免API限制）
const analysis = $input.first().json;
const recordsToDelete = analysis.records_to_delete || [];

if (recordsToDelete.length === 0) {
  console.log('没有需要删除的记录');
  return [];
}

console.log(`准备删除 ${recordsToDelete.length} 条重复记录`);

// 每批删除10条（避免触发API频率限制）
const batchSize = 10;
const batches = [];

for (let i = 0; i < recordsToDelete.length; i += batchSize) {
  const batch = recordsToDelete.slice(i, i + batchSize);
  batches.push({
    batch_number: Math.floor(i / batchSize) + 1,
    total_batches: Math.ceil(recordsToDelete.length / batchSize),
    record_ids: batch.map(r => r.record_id),
    records: batch
  });
}

console.log(`分为 ${batches.length} 批次处理`);

return batches;

// 汇总删除结果
const allResults = $input.all();

let successCount = 0;
let failCount = 0;

allResults.forEach(result => {
  if (result.json?.code === 0 || result.json?.data) {
    successCount += result.json.batch_size || 1;
  } else {
    failCount++;
  }
});

const summary = `
╔════════════════════════════════════════════════╗
║       删除操作完成 (Workflow C v1.2)           ║
╚════════════════════════════════════════════════╝

✅ 成功删除: ${successCount} 条记录
❌ 失败: ${failCount} 批次
📊 处理批次: ${allResults.length} 批
⏰ 完成时间: ${new Date().toLocaleString('zh-CN', {timeZone: 'Asia/Shanghai'})}

🎉 数据库已优化，重复记录已清理！

════════════════════════════════════════════════
`;

console.log(summary);

return [{
  json: {
    success_count: successCount,
    fail_count: failCount,
    total_batches: allResults.length,
    completion_time: new Date().toISOString(),
    message: '去重操作完成'
  }
}];

console.log('\n✅ 没有发现重复记录，无需删除操作');
console.log(`执行时间: ${new Date().toLocaleString('zh-CN', {timeZone: 'Asia/Shanghai'})}`);

return [{
  json: {
    message: '没有重复记录',
    action: 'skipped',
    execution_time: new Date().toISOString()
  }
}];
